class Solution {    
    public int numberOfSubstrings(String s) {
        //your code goes here
        int[] hash = new int[3];
        int n = s.length();
        int numSubstring = 0, count =  0;

        int left = 0, right = 0;

        while(right < n) {

            char ch1 = s.charAt(right);

            if(hash[ch1-'a'] == 0) 
                count++;

            hash[ch1-'a']++;

            while(count == 3) {
                numSubstring += (n - right);
                char ch2 = s.charAt(left);

                hash[ch2-'a']--;

                if(hash[ch2-'a'] == 0)
                    count--;

                left++;
            }

            right++;
        }

        return numSubstring;
    }
}
```

