class Solution {    
    numberOfSubstrings(s) {

        const n = s.length;
        let totalCount = 0;
        let l = 0;
        let r= 0;
        const freqMap = new Map();

        while ( r < n) {
            // add the new character to the map.
            freqMap.set(s[r], (freqMap.get(s[r]) || 0) + 1);

            // once we hit 3 unique characters got a, b and c
            // we add n-r to total count ( as all substrings starting with this l to r segment are also valid)
            // we try to shrink l to find new starting segments while maintaining the map size to be 3


            while (freqMap.size === 3) {
                totalCount += (n-r);
                freqMap.set(s[l], freqMap.get(s[l]) - 1);
                if(!freqMap.get(s[l])) {
                    freqMap.delete(s[l]);
                }
                l++;
            }
            // expand r till we hit a valid substring beginning
            r++;
        }

        return totalCount;
